// Manual-P/Invoke driver for the x86_64 (SysV) thunk-backend gate.
//
// Each [DllImport] below targets a generated `thunk_*` cdecl entry point in the
// wrapper dylib (FixtureLibSwiftBindings). The thunk converts the cdecl call to
// swiftcc and forwards to the real Swift symbol, so a correct round-trip here
// proves the thunk's register/struct/error handling for x86_64.
//
// EntryPoint names live in ThunkSymbols (generated by the gate from FixtureLib.cs)
// so this file never hard-codes the FNV-derived hash suffixes.

using System;
using System.Runtime.InteropServices;

[StructLayout(LayoutKind.Sequential)]
internal struct Mixed
{
    public int I;     // Int32 @ 0
    public float F;   // Float @ 4
    public long J;    // Int64 @ 8
    public double D;  // Double @ 16  (total 24 bytes -> sret on cdecl)
}

internal static unsafe class Program
{
    private const string Lib = "FixtureLibSwiftBindings";

    [DllImport(Lib, EntryPoint = ThunkSymbols.Init, CallingConvention = CallingConvention.Cdecl)]
    private static extern IntPtr CounterInit(long start);

    [DllImport(Lib, EntryPoint = ThunkSymbols.AddAndGet, CallingConvention = CallingConvention.Cdecl)]
    private static extern long AddAndGet(long delta, IntPtr self);

    [DllImport(Lib, EntryPoint = ThunkSymbols.Snapshot, CallingConvention = CallingConvention.Cdecl)]
    private static extern Mixed Snapshot(double scale, IntPtr self);

    [DllImport(Lib, EntryPoint = ThunkSymbols.CheckedAdd, CallingConvention = CallingConvention.Cdecl)]
    private static extern long CheckedAdd(long delta, IntPtr self, out IntPtr error);

    [DllImport(Lib, EntryPoint = ThunkSymbols.Origin, CallingConvention = CallingConvention.Cdecl)]
    private static extern long Origin();

    [DllImport(Lib, EntryPoint = ThunkSymbols.MakeMixed, CallingConvention = CallingConvention.Cdecl)]
    private static extern Mixed MakeMixed(long @base);

    private static int _fails;

    private static void Check(string name, bool ok, string detail)
    {
        Console.WriteLine($"[{(ok ? "PASS" : "FAIL")}] {name}: {detail}");
        if (!ok) _fails++;
    }

    private static int Main()
    {
        Console.WriteLine($"Arch={RuntimeInformation.ProcessArchitecture}");
        if (RuntimeInformation.ProcessArchitecture != Architecture.X64)
        {
            Console.WriteLine("FAIL: driver must run as x86_64 (launch under `arch -x86_64`).");
            return 2;
        }

        // instance method, self in %r13
        IntPtr c1 = CounterInit(100);
        long r1 = AddAndGet(5, c1);
        Check("AddAndGet", r1 == 105, $"{r1} (expect 105)");

        // >16B mixed-width return-by-value (return-store bridge)
        IntPtr c2 = CounterInit(7);
        Mixed m = Snapshot(3.0, c2);
        Check("Snapshot mixed", m.I == 7 && m.F == 14f && m.J == 7 && m.D == 21.0,
            $"i={m.I} f={m.F} j={m.J} d={m.D} (expect 7/14/7/21)");

        // throwing instance method (swifterror, %r12)
        IntPtr c3 = CounterInit(10);
        long r3 = CheckedAdd(5, c3, out IntPtr e1);
        Check("CheckedAdd ok", r3 == 15 && e1 == IntPtr.Zero, $"{r3} err=0x{e1.ToInt64():x} (expect 15 / null)");
        CheckedAdd(-1, c3, out IntPtr e2);
        Check("CheckedAdd throws", e2 != IntPtr.Zero, $"err=0x{e2.ToInt64():x} (expect nonzero)");

        // static method (metatype accessor)
        long o = Origin();
        Check("Origin static", o == 0, $"{o} (expect 0)");

        // static method + mixed-width return (metatype + return bridge)
        Mixed mm = MakeMixed(4);
        Check("MakeMixed static", mm.I == 4 && mm.F == 4.5f && mm.J == 8 && mm.D == 6.0,
            $"i={mm.I} f={mm.F} j={mm.J} d={mm.D} (expect 4/4.5/8/6)");

        Console.WriteLine(_fails == 0 ? "ALL PASS" : $"{_fails} FAIL");
        return _fails == 0 ? 0 : 1;
    }
}
